"use client"

import * as React from "react"
import {
  DayPicker,
  getDefaultClassNames,
  type DayButton,
  type Locale,
} from "react-day-picker"

import { cn } from "@/lib/utils"
import { Button, buttonVariants } from "@/registry/brutalist/ui/button"
import { ChevronLeftIcon, ChevronRightIcon, ChevronDownIcon } from "lucide-react"

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  locale,
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>["variant"]
}) {
  const defaultClassNames = getDefaultClassNames()

  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        "group/calendar bg-background p-2 [--cell-radius:var(--radius-md)] [--cell-size:--spacing(7)] in-data-[slot=card-content]:bg-transparent in-data-[slot=popover-content]:bg-transparent",
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className
      )}
      captionLayout={captionLayout}
      locale={locale}
      formatters={{
        formatMonthDropdown: (date) =>
          date.toLocaleString(locale?.code, { month: "short" }),
        ...formatters,
      }}
      classNames={{
        root: cn("w-fit", defaultClassNames.root),
        months: cn(
          "relative flex flex-col gap-4 md:flex-row",
          defaultClassNames.months
        ),
        month: cn("flex w-full flex-col gap-4", defaultClassNames.month),
        nav: cn(
          "absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1",
          defaultClassNames.nav
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none aria-disabled:opacity-50",
          defaultClassNames.button_previous
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) p-0 select-none aria-disabled:opacity-50",
          defaultClassNames.button_next
        ),
        month_caption: cn(
          "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
          defaultClassNames.month_caption
        ),
        dropdowns: cn(
          "flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium",
          defaultClassNames.dropdowns
        ),
        dropdown_root: cn(
          "relative rounded-(--cell-radius)",
          defaultClassNames.dropdown_root
        ),
        dropdown: cn(
          "absolute inset-0 bg-popover opacity-0",
          defaultClassNames.dropdown
        ),
        caption_label: cn(
          "font-medium select-none",
          captionLayout === "label"
            ? "text-sm"
            : "flex items-center gap-1 rounded-(--cell-radius) text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
          defaultClassNames.caption_label
        ),
        month_grid: cn("w-full border-collapse", defaultClassNames.month_grid),
        weekdays: cn("flex", defaultClassNames.weekdays),
        weekday: cn(
          "flex-1 rounded-(--cell-radius) text-[0.8rem] font-normal text-muted-foreground select-none",
          defaultClassNames.weekday
        ),
        week: cn("mt-2 flex w-full", defaultClassNames.week),
        week_number_header: cn(
          "w-(--cell-size) select-none",
          defaultClassNames.week_number_header
        ),
        week_number: cn(
          "text-[0.8rem] text-muted-foreground select-none",
          defaultClassNames.week_number
        ),
        day: cn(
          "group/day relative aspect-square h-full w-full rounded-(--cell-radius) p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-r-(--cell-radius)",
          props.showWeekNumber
            ? "[&:nth-child(2)[data-selected=true]_button]:rounded-l-(--cell-radius)"
            : "[&:first-child[data-selected=true]_button]:rounded-l-(--cell-radius)",
          defaultClassNames.day
        ),
        range_start: cn(
          "relative isolate z-0 rounded-l-(--cell-radius) bg-muted after:absolute after:inset-y-0 after:right-0 after:w-4 after:bg-muted",
          defaultClassNames.range_start
        ),
        range_middle: cn("rounded-none", defaultClassNames.range_middle),
        range_end: cn(
          "relative isolate z-0 rounded-r-(--cell-radius) bg-muted after:absolute after:inset-y-0 after:left-0 after:w-4 after:bg-muted",
          defaultClassNames.range_end
        ),
        today: cn(
          "rounded-(--cell-radius) bg-muted text-foreground data-[selected=true]:rounded-none",
          defaultClassNames.today
        ),
        outside: cn(
          "text-muted-foreground aria-selected:text-muted-foreground",
          defaultClassNames.outside
        ),
        disabled: cn(
          "text-muted-foreground opacity-50",
          defaultClassNames.disabled
        ),
        hidden: cn("invisible", defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => {
          return (
            <div
              data-slot="calendar"
              ref={rootRef}
              className={cn(className)}
              {...props}
            />
          )
        },
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === "left") {
            return (
              <ChevronLeftIcon className={cn("size-4", className)} {...props} />
            )
          }

          if (orientation === "right") {
            return (
              <ChevronRightIcon className={cn("size-4", className)} {...props} />
            )
          }

          return (
            <ChevronDownIcon className={cn("size-4", className)} {...props} />
          )
        },
        DayButton: ({ ...props }) => (
          <CalendarDayButton locale={locale} {...props} />
        ),
        WeekNumber: ({ children, ...props }) => {
          return (
            <td {...props}>
              <div className="flex size-(--cell-size) items-center justify-center text-center">
                {children}
              </div>
            </td>
          )
        },
        ...components,
      }}
      {...props}
    />
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> }) {
  const defaultClassNames = getDefaultClassNames()

  const ref = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <Button
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString(locale?.code)}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "relative isolate z-10 flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 border-0 leading-none font-normal group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50 data-[range-end=true]:rounded-(--cell-radius) data-[range-end=true]:rounded-r-(--cell-radius) data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-muted data-[range-middle=true]:text-foreground data-[range-start=true]:rounded-(--cell-radius) data-[range-start=true]:rounded-l-(--cell-radius) data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground data-[selected-single=true]:bg-primary data-[selected-single=true]:text-primary-foreground dark:hover:text-foreground [&>span]:text-xs [&>span]:opacity-70",
        defaultClassNames.day,
        className
      )}
      {...props}
    />
  )
}

export { Calendar, CalendarDayButton }

:root,
[data-brut-palette="paper"] {
  --background: oklch(0.985 0.004 95);
  --foreground: oklch(0.15 0.01 65);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.82 0.18 88);
  --primary-foreground: oklch(0.13 0.01 70);
  --secondary: oklch(0.88 0.105 210);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.94 0.018 90);
  --muted-foreground: oklch(0.38 0.02 65);
  --accent: oklch(0.72 0.2 20);
  --accent-foreground: oklch(0.99 0 0);
  --destructive: oklch(0.61 0.24 28);
  --border: oklch(0.15 0.01 65);
  --input: oklch(0.15 0.01 65);
  --ring: oklch(0.56 0.23 264);
  --brut-shadow-color: oklch(0.15 0.01 65);
  --brut-grid-color: oklch(0.15 0.01 65 / 9%);
}

:root {
  --chart-1: var(--primary);
  --chart-2: var(--secondary);
  --chart-3: var(--accent);
  --chart-4: var(--destructive);
  --chart-5: var(--muted-foreground);
  --sidebar: var(--card);
  --sidebar-foreground: var(--card-foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);
}

[data-brut-palette="signal"] {
  --background: oklch(0.91 0.16 96);
  --foreground: oklch(0.13 0.01 70);
  --card: oklch(0.985 0.025 96);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.025 96);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.15 0.01 70);
  --primary-foreground: oklch(0.93 0.17 96);
  --secondary: oklch(0.73 0.2 28);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.86 0.11 96);
  --muted-foreground: oklch(0.31 0.03 70);
  --accent: oklch(0.75 0.13 222);
  --accent-foreground: oklch(0.13 0.01 70);
  --destructive: oklch(0.55 0.24 28);
  --border: oklch(0.13 0.01 70);
  --input: oklch(0.13 0.01 70);
  --ring: oklch(0.55 0.24 28);
  --brut-shadow-color: oklch(0.13 0.01 70);
  --brut-grid-color: oklch(0.13 0.01 70 / 12%);
}

[data-brut-palette="sky"] {
  --background: oklch(0.92 0.055 235);
  --foreground: oklch(0.16 0.04 255);
  --card: oklch(0.98 0.018 230);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.018 230);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.52 0.2 255);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.88 0.16 92);
  --secondary-foreground: oklch(0.16 0.04 255);
  --muted: oklch(0.86 0.045 235);
  --muted-foreground: oklch(0.36 0.055 255);
  --accent: oklch(0.71 0.18 28);
  --accent-foreground: oklch(0.16 0.04 255);
  --destructive: oklch(0.56 0.24 27);
  --border: oklch(0.16 0.04 255);
  --input: oklch(0.16 0.04 255);
  --ring: oklch(0.67 0.2 28);
  --brut-shadow-color: oklch(0.16 0.04 255);
  --brut-grid-color: oklch(0.16 0.04 255 / 11%);
}

:root,
[data-brut-strength="solid"] {
  --brut-border: 2px;
  --brut-shadow-x: 4px;
  --brut-shadow-y: 4px;
  --brut-panel-shadow-x: 7px;
  --brut-panel-shadow-y: 7px;
  --brut-hover: -1px;
  --brut-press: 2px;
  --brut-weight: 700;
}

[data-brut-strength="soft"] {
  --brut-border: 1px;
  --brut-shadow-x: 2px;
  --brut-shadow-y: 2px;
  --brut-panel-shadow-x: 4px;
  --brut-panel-shadow-y: 4px;
  --brut-hover: -1px;
  --brut-press: 1px;
  --brut-weight: 600;
}

[data-brut-strength="loud"] {
  --brut-border: 3px;
  --brut-shadow-x: 6px;
  --brut-shadow-y: 6px;
  --brut-panel-shadow-x: 9px;
  --brut-panel-shadow-y: 9px;
  --brut-hover: -2px;
  --brut-press: 3px;
  --brut-weight: 800;
}

:root,
[data-brut-radius="sharp"] {
  --radius: 0rem;
}

[data-brut-radius="cut"] {
  --radius: 0.375rem;
}

[data-brut-radius="chunky"] {
  --radius: 0.875rem;
}

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 60%, transparent);
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    background-image:
      linear-gradient(var(--brut-grid-color) 1px, transparent 1px),
      linear-gradient(90deg, var(--brut-grid-color) 1px, transparent 1px);
    background-size: 28px 28px;
  }

  ::selection {
    background: var(--primary);
    color: var(--primary-foreground);
  }
}

@layer components {
  .brut-panel {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-panel-shadow-x) var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-surface {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-control {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: var(--brut-weight);
    transition: transform 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
  }

  .brut-control:hover:not(:disabled, [data-disabled]) {
    transform: translate(var(--brut-hover), var(--brut-hover));
    box-shadow: calc(var(--brut-shadow-x) - var(--brut-hover)) calc(var(--brut-shadow-y) - var(--brut-hover)) 0 var(--brut-shadow-color);
  }

  .brut-control:active:not(:disabled, [data-disabled]),
  .brut-control[data-pressed] {
    transform: translate(var(--brut-press), var(--brut-press));
    box-shadow: 0 0 0 var(--brut-shadow-color);
  }

  .brut-quiet {
    border: var(--brut-border) solid transparent;
    border-radius: var(--radius);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-quiet:hover {
    border-color: var(--border);
    background: var(--muted);
  }

  .brut-focus:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 3px;
  }

  .brut-input {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input-group:focus-within {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-input-group:has([aria-invalid="true"]):focus-within {
    outline-color: var(--destructive);
  }

  .brut-otp-group:has([data-active="true"]) {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-otp-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-otp-group:has([aria-invalid="true"]):has([data-active="true"]) {
    outline-color: var(--destructive);
  }

  .brut-chip {
    border: 2px solid var(--border);
    border-radius: calc(var(--radius) * 0.75);
    box-shadow: 2px 2px 0 var(--brut-shadow-color);
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .brut-check {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.5);
    background: var(--card);
    box-shadow: 2px 2px 0 var(--brut-shadow-color);
  }

  .brut-avatar {
    border: var(--brut-border) solid var(--border);
    background: var(--card);
    box-shadow: calc(var(--brut-border) + 1px) calc(var(--brut-border) + 1px) 0 var(--brut-shadow-color);
  }

  .brut-separator {
    background: var(--border);
  }

  .brut-dialog {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: 14px 14px 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="right"] {
    border-left: var(--brut-border) solid var(--border);
    border-radius: var(--radius) 0 0 var(--radius);
    box-shadow: calc(0px - var(--brut-panel-shadow-x)) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="left"] {
    border-right: var(--brut-border) solid var(--border);
    border-radius: 0 var(--radius) var(--radius) 0;
    box-shadow: var(--brut-panel-shadow-x) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="bottom"] {
    border-top: var(--brut-border) solid var(--border);
    border-radius: var(--radius) var(--radius) 0 0;
    box-shadow: 0 calc(0px - var(--brut-panel-shadow-y)) 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="top"] {
    border-bottom: var(--brut-border) solid var(--border);
    border-radius: 0 0 var(--radius) var(--radius);
    box-shadow: 0 var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-popover {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-switch {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: 3px 3px 0 var(--brut-shadow-color);
  }

  .brut-switch-thumb {
    border-radius: calc(var(--radius) * 0.75);
  }

  .brut-progress {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    background: var(--card);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
